    		set obj.LOOKUPKEY= snap.GetData(1)
    		set obj.IDCDID = snap.GetData(2)
    		set obj.CLMFICDINDPROC= snap.GetData(3)
    		set obj.CODE837QUAL= snap.GetData(4)
    		set obj.CLMDPOAIND= snap.GetData(5)
    		set obj.CLHIIPDT= snap.GetData(6)
			do listHI67.Insert(obj)	 
			// kill obj
			continue      
		}
	}

}
do snap.Rewind()
Quit st

